# Code generated by Claude
"""
Tests of src/arm_kinematics.py (batch forward kinematics, the analytic Jacobian and the bounded damped-least-squares IK).

    MUJOCO_GL=egl python experiments/arm_kinematics_test.py

1. Forward kinematics against MuJoCo's own, both arms, 300 random in-limit poses: the tool point's position and rotation in the torso frame (< 1e-12), a point offset from the tool
   point (the pad centre derived by src/gripper_geometry.py), and the shoulder origin (the link0 position).
2. The analytic Jacobians against finite differences of the forward kinematics (position and the rotation of the hand frame).
3. The IK: from random starts to targets that are reachable by construction (the forward kinematics of other random poses): most converge from fully random starts (about 85 %: the rest sit in local minima against the joint limits), every one that does meets the
   tolerance, from a warm start (a neighbour's solution, 0.02 rad away) all converge in a few iterations, the joints stay inside the bounds, a target 2 m away never converges, and the pad-centre point (offset) is the one that is placed.
"""

import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.arm_kinematics import arm_chain, batch_fk, batch_fk_jac, position_constraint, shoulder_origin, solve_ik  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    sim = RobotSimulator(pedestal_lift=robot_specs.PEDESTAL_SPECS, cameras=None)
    m, d = sim.model, sim.data
    rng = np.random.default_rng(1)
    off = gripper_frame(m, "left")["pad_center_in_tcp"]
    torso = m.body("openarm_body_link0").id
    print("\n1. forward kinematics against MuJoCo")
    for side in ("left", "right"):
        chain = arm_chain(m, side)
        ids = arm_ids(m, side)
        lo, hi = m.jnt_range[ids["jnt"], 0], m.jnt_range[ids["jnt"], 1]
        Q = rng.uniform(lo, hi, (300, 7))
        p, R = batch_fk(chain, Q)
        pp, _ = batch_fk(chain, Q, off)
        e_p = e_R = e_o = 0.0
        tcp = m.body(f"openarm_{side}_hand_tcp").id
        for q, p_i, R_i, pp_i in zip(Q, p, R, pp):
            for a, v in zip(ids["qadr"], q):
                d.qpos[a] = v
            mujoco.mj_kinematics(m, d)
            Rt = d.xmat[torso].reshape(3, 3)
            p_m = Rt.T @ (d.xpos[tcp] - d.xpos[torso])
            R_m = Rt.T @ d.xmat[tcp].reshape(3, 3)
            o_m = Rt.T @ (d.xpos[tcp] + d.xmat[tcp].reshape(3, 3) @ off - d.xpos[torso])
            e_p, e_R, e_o = max(e_p, np.abs(p_i - p_m).max()), max(e_R, np.abs(R_i - R_m).max()), max(e_o, np.abs(pp_i - o_m).max())
        check(f"{side}: tool point position and rotation equal MuJoCo's", max(e_p, e_R) < 1e-12, f"max error {max(e_p, e_R):.1e}")
        check(f"{side}: the point offset in the tool point frame (pad centre) equals MuJoCo's", e_o < 1e-12, f"max error {e_o:.1e}")
        mujoco.mj_kinematics(m, d)
        Rt = d.xmat[torso].reshape(3, 3)
        sh = Rt.T @ (d.xpos[m.body(f"openarm_{side}_link0").id] - d.xpos[torso])
        check(f"{side}: the shoulder origin is the link0 position in the torso frame", np.abs(shoulder_origin(chain) - sh).max() < 1e-12, f"{np.round(shoulder_origin(chain), 4)}")

    print("\n2. Jacobians against finite differences")
    for side in ("left", "right"):
        chain = arm_chain(m, side)
        ids = arm_ids(m, side)
        lo, hi = m.jnt_range[ids["jnt"], 0], m.jnt_range[ids["jnt"], 1]
        Q = rng.uniform(lo + 0.2, hi - 0.2, (200, 7))
        p, R, Jv, Jw = batch_fk_jac(chain, Q, off)
        eps = 1e-6
        e_v = e_w = 0.0
        for j in range(7):
            Qp = Q.copy()
            Qp[:, j] += eps
            p2, R2 = batch_fk(chain, Qp, off)
            e_v = max(e_v, np.abs((p2 - p) / eps - Jv[:, :, j]).max())
            dR = (R2 - R) / eps                                            # dR = [w]x R, so the hand's z axis changes by w x z
            e_w = max(e_w, np.abs(dR[:, :, 2] - np.cross(Jw[:, :, j], R[:, :, 2])).max())
        check(f"{side}: position Jacobian matches finite differences", e_v < 1e-5, f"max error {e_v:.1e}")
        check(f"{side}: angular Jacobian matches finite differences", e_w < 1e-5, f"max error {e_w:.1e}")

    print("\n3. IK")
    for side in ("left", "right"):
        chain = arm_chain(m, side)
        ids = arm_ids(m, side)
        lo, hi = m.jnt_range[ids["jnt"], 0] + 0.17, m.jnt_range[ids["jnt"], 1] - 0.17     # a 10 degree margin
        Qt = rng.uniform(lo, hi, (2000, 7))
        target, _ = batch_fk(chain, Qt, off)
        Q0 = rng.uniform(lo, hi, (2000, 7))
        Q, ok, it = solve_ik(chain, Q0, lo, hi, position_constraint(target, 5e-4), off)
        p, _ = batch_fk(chain, Q, off)
        err = np.linalg.norm(p - target, axis=1)
        check(f"{side}: at least 80 % of 2000 random reachable targets converge from random starts", ok.mean() > 0.8, f"{100 * ok.mean():.1f} %, median {int(np.median(it[ok]))} iterations")
        check(f"{side}: every converged solution is within the 0.5 mm tolerance and inside the bounds", (err[ok] < 5e-4).all() and (Q >= lo - 1e-12).all() and (Q <= hi + 1e-12).all(), f"worst {1000 * err[ok].max():.3f} mm")
        Qw, okw, itw = solve_ik(chain, np.clip(Qt + rng.normal(0, 0.02, Qt.shape), lo, hi), lo, hi, position_constraint(target, 5e-4), off)
        check(f"{side}: from a warm start (0.02 rad of noise) all 2000 converge", okw.all(), f"median {int(np.median(itw))} iterations")
        far = np.tile([2.0, 0.0, 0.5], (200, 1))
        _, ok2, _ = solve_ik(chain, Q0[:200], lo, hi, position_constraint(far, 5e-4), off)
        check(f"{side}: a target 2 m away never converges", not ok2.any())
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
